WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_complex_compare'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '复杂比较', 'kp-xingce-data-analysis-complex-compare', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "复杂比较"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "对于带有“均”、“逐年递增”等绝对化描述的选项，采用反面找茬法进行定性判决。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "选项特征：“2018~2023这五年间，A 的增速逐年递增。” 或 “材料中列出的10个省份，产值均超过了1000亿。”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心战术：反面找茬"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这类选项，你的目标不再是去证明它是对的，而是带着显微镜去扫视材料，试图找到一个“反例”来证明它是错的。只要找到一个，立刻打叉。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[遇到含'均'/'连年'字眼的选项] --> B[将目光变成雷达, 沿图表快速平扫]\nB --> C{是否寻找到了凹陷点/异常小值?}\nC -- 是(比如某年突然降了) --> D[发现反例, 判该选项死刑!]\nC -- 扫完一遍没找到反例 --> E[该选项大概率正确, 但先放着作为备选]\nD --> F[去看下一个选项]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 选项：2018年至2023年，我国大豆产量连年保持 10% 以上的高速增长。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "定位字眼：“连年保持”。这是绝对化的全称量词。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "回材料扫描图表：看着折线图或者表格的增速那一列。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找反例：发现 2020 年的增速是 8.5%，小于 10%。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出结论：直接打叉，该选项错误。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "极端年份陷阱（没有基数）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "图表给了 2018-2023 年绝对量的柱子，没有给增速折线。题目问“18-23年增速连年上升”。注意！你用 19年产量减18年产量，算出了第一年的增速。但是 2018年本身的增速你是算不出来的！因为材料没给2017年的数据。这时候如果图表只有 5 个年份能算出增速，千万别说“这6年都……”！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "培养对图表上特殊节点（极高点、极低点、拐点）的直觉。读图第一眼就先把这些反常点圈出来，后面验证绝对化选项时直接去查圈出的点。"}]}]}$$ AS jsonb), NULL, '复杂比较的核心考点与实战推导。', category_node.id, CAST('["资料分析", "复杂比较"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_complex_compare", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
